// 参考解：O(n) 原地删除
#include <iostream>
using namespace std;

int main() {
    int n;
    if (!(cin >> n)) return 0;
    int a[1005];
    for (int i = 0; i < n; i++) cin >> a[i];
    int s, t;
    cin >> s >> t;

    if (s > t) { int tmp = s; s = t; t = tmp; }

    int k = 0;                         // k 是"保留下来的元素个数"
    for (int i = 0; i < n; i++) {
        if (a[i] < s || a[i] > t) {    // 不在区间内就保留
            a[k++] = a[i];
        }
    }

    if (k == 0) {
        cout << "empty\n";
        return 0;
    }
    for (int i = 0; i < k; i++) {
        cout << a[i] << (i + 1 == k ? '\n' : ' ');
    }
    return 0;
}
